def word_exists_in_grid(grid, word):
    if not word:
        return True
    if not grid or not grid[0]:
        return False
    rows, cols = len(grid), len(grid[0])

    def backtrack(r, c, i, visited):
        if grid[r][c] != word[i]:
            return False
        if i == len(word) - 1:
            return True
        visited.add((r, c))
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                if backtrack(nr, nc, i + 1, visited):
                    visited.discard((r, c))
                    return True
        visited.discard((r, c))
        return False

    for r in range(rows):
        for c in range(cols):
            if backtrack(r, c, 0, set()):
                return True
    return False
